using System;
using System.Collections.Generic;
using System.Diagnostics;
using System.IO;
using System.Reflection;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Controls.Primitives;
using System.Windows.Input;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using System.Windows.Shapes;
using System.Windows.Threading;
using Path=System.IO.Path;
namespace RazerBatteryTray.Desktop {
 internal static class FinesseStageATests {
  static string output;static int failed;static readonly List<string> results=new List<string>();
  static Window window;static StackPanel panel;static Button primary,ordinary;static CheckBox toggle;static ComboBox combo;
  static void Check(bool value,string message){if(!value)throw new Exception(message);}
  static void Pump(int ms=30){var f=new DispatcherFrame();var t=new DispatcherTimer{Interval=TimeSpan.FromMilliseconds(ms)};t.Tick+=(s,e)=>{t.Stop();f.Continue=false;};t.Start();Dispatcher.PushFrame(f);}
  static void Test(string name,Action body){Ui.ReducedMotion=false;primary.IsEnabled=ordinary.IsEnabled=toggle.IsEnabled=combo.IsEnabled=true;window.Activate();Pump();UiMotion.SettleAll();try{body();results.Add("PASS\t"+name);Console.WriteLine("PASS "+name);}catch(Exception e){failed++;results.Add("FAIL\t"+name+"\t"+e.Message);Console.WriteLine("FAIL "+name+": "+e.Message);}finally{combo.IsDropDownOpen=false;UiMotion.SettleAll();}}
  static void Mouse(Control b,bool down){b.RaiseEvent(new MouseButtonEventArgs(System.Windows.Input.Mouse.PrimaryDevice,0,MouseButton.Left){RoutedEvent=down?UIElement.PreviewMouseLeftButtonDownEvent:UIElement.PreviewMouseLeftButtonUpEvent});}
  static void SendKey(Control b,bool down,Key key){b.RaiseEvent(new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(window),0,key){RoutedEvent=down?UIElement.PreviewKeyDownEvent:UIElement.PreviewKeyUpEvent});}
  static ScaleTransform Press(Button b){return UiMotion.Transform(UiMotion.ButtonVisual(b)).Press;}
  static ScaleTransform Thumb(){return (ScaleTransform)((TransformGroup)((Ellipse)toggle.Template.FindName("Dot",toggle)).RenderTransform).Children[0];}
  static void Capture(string name,FrameworkElement v){if(ReferenceEquals(v,panel))v=(FrameworkElement)VisualTreeHelper.GetChild(window,0);v.UpdateLayout();var b=new RenderTargetBitmap((int)Math.Ceiling(v.ActualWidth),(int)Math.Ceiling(v.ActualHeight),96,96,PixelFormats.Pbgra32);b.Render(v);var p=new PngBitmapEncoder();p.Frames.Add(BitmapFrame.Create(b));using(var f=new FileStream(Path.Combine(output,name+".png"),FileMode.CreateNew))p.Save(f);}
  static double Luma(Color c){Func<byte,double> p=v=>{double x=v/255.0;return x<=.04045?x/12.92:Math.Pow((x+.055)/1.055,2.4);};return .2126*p(c.R)+.7152*p(c.G)+.0722*p(c.B);}
  static double Contrast(Color a,Color b){double x=Luma(a),y=Luma(b);return (Math.Max(x,y)+.05)/(Math.Min(x,y)+.05);}
  static Color ColorOf(Brush b){return ((SolidColorBrush)b).Color;}
  static Color Composite(Color c,double opacity,Color bg){return Color.FromRgb((byte)Math.Round(c.R*opacity+bg.R*(1-opacity)),(byte)Math.Round(c.G*opacity+bg.G*(1-opacity)),(byte)Math.Round(c.B*opacity+bg.B*(1-opacity)));}
  static void ProcessKey(Key key,bool down){InputManager.Current.ProcessInput(new KeyEventArgs(Keyboard.PrimaryDevice,PresentationSource.FromVisual(window),0,key){RoutedEvent=down?Keyboard.KeyDownEvent:Keyboard.KeyUpEvent});}
  [System.Runtime.InteropServices.StructLayout(System.Runtime.InteropServices.LayoutKind.Sequential)]struct NativeKeyData{internal ushort VirtualKey,Scan;internal uint Flags,Time;internal IntPtr Extra;}
  [System.Runtime.InteropServices.StructLayout(System.Runtime.InteropServices.LayoutKind.Explicit,Size=40)]struct NativeInput{[System.Runtime.InteropServices.FieldOffset(0)]internal uint Type;[System.Runtime.InteropServices.FieldOffset(8)]internal NativeKeyData Key;}
  [System.Runtime.InteropServices.DllImport("user32.dll")]static extern IntPtr GetForegroundWindow();
  [System.Runtime.InteropServices.DllImport("user32.dll",SetLastError=true)]static extern uint SendInput(uint count,NativeInput[] input,int size);
  static void NativeTab(){IntPtr own=new System.Windows.Interop.WindowInteropHelper(window).Handle;Check(window.IsActive&&GetForegroundWindow()==own,"Safety stop: isolated Stage A window is not foreground; no native key sent");var events=new[]{new NativeInput{Type=1,Key=new NativeKeyData{VirtualKey=9}},new NativeInput{Type=1,Key=new NativeKeyData{VirtualKey=9,Flags=2}}};Check(GetForegroundWindow()==own,"Safety stop before native Tab");Check(SendInput(2,events,40)==2,"Native Tab not accepted");}
  static void Record(string name,Action begin,Action interrupt){begin();var rows=new List<string>{"elapsed_ms,button_scale,toggle_scale,active,rendering"};var clock=Stopwatch.StartNew();for(int i=0;i<16;i++){if(i==4)interrupt();Pump(25);Capture(name+"-"+i.ToString("D2"),panel);rows.Add(clock.ElapsedMilliseconds+","+Press(primary).ScaleX.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+","+Thumb().ScaleX.ToString("R",System.Globalization.CultureInfo.InvariantCulture)+","+SpringMotion.ActiveCount+","+SpringMotion.RenderingSubscribed);}File.WriteAllLines(Path.Combine(output,name+".csv"),rows);}
  [STAThread]static int Main(string[] args){output=Path.GetFullPath(args[0]);Directory.CreateDirectory(output);var app=new Application{ShutdownMode=ShutdownMode.OnExplicitShutdown};DesktopApp.LoadTheme(app);
   panel=new StackPanel{Margin=new Thickness(28),Background=Ui.Background};panel.Children.Add(Ui.Text("Stage A · 隔离组件审阅 / local preview",21));panel.Children.Add(Ui.Text("现有主题与布局保留 · 控件中断时回到稳定状态",13,Ui.Muted));
   primary=Ui.PrimaryButton("保存并应用 / Primary",()=>{});ordinary=Ui.Button("普通按钮 / Space Enter",()=>{});panel.Children.Add(Ui.Row(primary,ordinary));
   toggle=Ui.Toggle("开关：Space、失焦与禁用回退",false,value=>{});panel.Children.Add(toggle);combo=Ui.Combo(new[]{"下拉选项一 / One","下拉选项二 / Two","下拉选项三 / Three"});panel.Children.Add(combo);panel.Children.Add(Ui.Input("输入框 / keyboard focus"));
   window=new Window{Title="雷云 Lite · Stage A 独立预览（无硬件）",Width=760,Height=450,Content=panel,Background=Ui.Background,ShowInTaskbar=false};app.MainWindow=window;window.Show();window.Activate();Pump(100);
   var target=PresentationSource.FromVisual(window).CompositionTarget.TransformToDevice;File.WriteAllText(Path.Combine(output,"environment.txt"),"WPF device scale="+target.M11+","+target.M22+"; RenderTargetBitmap DPI=96; ClientAreaAnimation="+SystemParameters.ClientAreaAnimation+"; HighContrast="+SystemParameters.HighContrast+"; target app version="+AppVersion.Number+"; isolated UI regression fixture; native input limited to foreground-guarded Tab in isolated test window.");
   try{
    Test("A01 button disable mid-press resets immediately without overriding disabled opacity",()=>{Mouse(primary,true);Pump(180);primary.IsEnabled=false;Capture("button-disabled-midpress",panel);Check(Math.Abs(Press(primary).ScaleX-1)<.0001&&Math.Abs(Press(primary).ScaleY-1)<.0001,"Disabled button retained pressed transform "+Press(primary).ScaleX);Check(primary.Opacity<1,"Disabled visual lost template opacity");});
    Test("A02 checkbox keyboard lost focus releases both press axes",()=>{toggle.Focus();SendKey(toggle,true,Key.Space);Pump(160);toggle.RaiseEvent(new KeyboardFocusChangedEventArgs(Keyboard.PrimaryDevice,0,toggle,ordinary){RoutedEvent=Keyboard.LostKeyboardFocusEvent});Pump(350);Capture("toggle-focus-lost",panel);Check(Math.Abs(Thumb().ScaleX-1)<.0001&&Math.Abs(Thumb().ScaleY-1)<.0001,"Lost-focus checkbox retained press "+Thumb().ScaleX);});
    Test("A03 checkbox disable mid-press settles checked position and press immediately",()=>{toggle.IsChecked=true;SendKey(toggle,true,Key.Space);Pump(160);toggle.IsEnabled=false;Capture("toggle-disabled-midpress",panel);Check(Math.Abs(Thumb().ScaleX-1)<.0001&&Math.Abs(Thumb().ScaleY-1)<.0001,"Disabled checkbox retained press "+Thumb().ScaleX);var move=(TranslateTransform)((TransformGroup)((Ellipse)toggle.Template.FindName("Dot",toggle)).RenderTransform).Children[1];Check(move.X==18,"Disable lost checked terminal position");});
    Test("A04 keyboard focus template contrast >=3 in both themes and dimensions unchanged",()=>{foreach(string theme in new[]{"classic","fluent"}){Ui.ApplyTheme(theme);var sample=new Control{Style=(Style)app.Resources["KeyboardFocus"],Width=250,Height=34};panel.Children.Add(sample);Pump();var border=(Border)sample.Template.LoadContent();border.SetResourceReference(Border.BorderBrushProperty,"SelectionIndicator");sample.ApplyTemplate();var root=VisualTreeHelper.GetChild(sample,0) as Border;Check(root!=null,"Focus template root missing");double contrast=Contrast(ColorOf(root.BorderBrush),ColorOf(Ui.Brush("CardBackground")));File.AppendAllText(Path.Combine(output,"focus-contrast.tsv"),theme+"\t"+contrast+Environment.NewLine);Capture(theme+"-focus-template",panel);panel.Children.Remove(sample);Check(contrast>=3,"Keyboard focus contrast "+theme+"="+contrast);}});
    Test("A05 click callbacks remain synchronous and repeated transform retrieval does not accumulate",()=>{int clicked=0;var b=Ui.Button("同步点击 / Immediate",()=>clicked++);panel.Children.Add(b);Pump();var g=UiMotion.Transform(UiMotion.ButtonVisual(b)).Group;for(int i=0;i<100;i++){Mouse(b,true);typeof(Button).GetMethod("OnClick",BindingFlags.Instance|BindingFlags.NonPublic).Invoke(b,null);Mouse(b,false);Check(clicked==i+1,"Click delayed by motion");Check(ReferenceEquals(g,UiMotion.Transform(UiMotion.ButtonVisual(b)).Group)&&g.Children.Count==3,"Transform group accumulated");}panel.Children.Remove(b);Pump();});
    Test("A06 reduced motion, hidden owner and unload settle without background rendering",()=>{Mouse(primary,true);SendKey(toggle,true,Key.Space);Ui.ReducedMotion=true;Check(Press(primary).ScaleX==1&&Thumb().ScaleX==1,"Reduced motion retained press");Ui.ReducedMotion=false;Mouse(primary,true);primary.Visibility=Visibility.Collapsed;Pump();Check(Press(primary).ScaleX==1,"Hidden button retained press");primary.Visibility=Visibility.Visible;panel.Children.Remove(toggle);Pump();Check(Thumb().ScaleX==1,"Unloaded toggle retained press");panel.Children.Add(toggle);Pump();Check(SpringMotion.ActiveCount==0&&!SpringMotion.RenderingSubscribed,"Hidden/unloaded controls keep rendering");});
    Test("A07 popup 100 close/reopen cycles, Escape-shaped close and unload leave no visible popup",()=>{for(int i=0;i<100;i++){combo.IsDropDownOpen=true;Pump(2);combo.IsDropDownOpen=false;Pump(2);}var popup=(Popup)combo.Template.FindName("PART_Popup",combo);Check(!popup.IsOpen,"Popup remains open");Pump(1000);Check(SpringMotion.ActiveCount==0&&!SpringMotion.RenderingSubscribed,"Popup rendering leaked");combo.IsDropDownOpen=true;Pump();panel.Children.Remove(combo);Pump();Check(!popup.IsOpen,"Unloaded combo left native popup");panel.Children.Add(combo);Pump();});
    Test("A08 theme rebuild and rollback retain checked state and transform isolation",()=>{for(int i=0;i<20;i++){Ui.ApplyTheme(i%2==0?"classic":"fluent");toggle.IsChecked=true;toggle.IsChecked=false;ElasticSwitch.RefreshAll();}Pump();Check(toggle.IsChecked==false&&Thumb().ScaleX==1,"Rollback/refresh state drift");Check(SpringMotion.ActiveCount==0,"Refresh created persistent animations");});
    Test("A09 checkbox save failure rolls state back synchronously without extra callback",()=>{int calls=0;var c=Ui.Toggle("保存失败回滚 / isolated failure",false,value=>{calls++;throw new IOException("isolated write failure");});panel.Children.Add(c);Pump();c.IsChecked=true;c.RaiseEvent(new RoutedEventArgs(ButtonBase.ClickEvent));Check(c.IsChecked==false&&calls==1,"Save rollback changed business timing or repeated callback");Pump(900);var move=(TranslateTransform)((TransformGroup)((Ellipse)c.Template.FindName("Dot",c)).RenderTransform).Children[1];Check(move.X==0,"Rollback thumb differs from checked state");panel.Children.Remove(c);});
    Test("A10 disabled controls keep readable composited text, semantic surface and native cursor",()=>{foreach(var theme in new[]{"classic","fluent"}){Ui.ApplyTheme(theme);primary.IsEnabled=toggle.IsEnabled=combo.IsEnabled=false;Check(primary.Cursor==Cursors.Arrow&&toggle.Cursor==Cursors.Arrow&&combo.Cursor==Cursors.Arrow,"Disabled control still advertises hand action");var parent=ColorOf(Ui.Background);foreach(Control c in new Control[]{primary,toggle,combo}){var background=c==primary?ColorOf(((Border)UiMotion.ButtonVisual(primary)).Background):c==combo?ColorOf(Ui.Brush("ControlBackground")):parent;double contrast=Contrast(Composite(ColorOf(c.Foreground),c.Opacity,parent),Composite(background,c.Opacity,parent));Check(contrast>=3,"Disabled text double-dimmed "+theme+"/"+c.GetType().Name+"="+contrast);File.AppendAllText(Path.Combine(output,"disabled-contrast.tsv"),theme+"\t"+c.GetType().Name+"\t"+contrast+Environment.NewLine);}Capture(theme+"-disabled-controls",panel);primary.IsEnabled=toggle.IsEnabled=combo.IsEnabled=true;}});
    Test("A11 application Space/Enter pipeline and guarded native Tab focus adorner",()=>{int clicks=0;var b=Ui.Button("键盘提交 / keyboard click",()=>clicks++);panel.Children.Add(b);Pump();b.Focus();ProcessKey(Key.Space,true);ProcessKey(Key.Space,false);Pump();Check(clicks==1,"Space click did not pass native WPF button pipeline");ProcessKey(Key.Enter,true);ProcessKey(Key.Enter,false);Pump();Check(clicks==2,"Enter click did not pass native WPF button pipeline");foreach(var theme in new[]{"classic","fluent"}){Ui.ApplyTheme(theme);b.Focus();NativeTab();Pump(100);var focused=Keyboard.FocusedElement as UIElement;Check(focused!=null&&!ReferenceEquals(focused,b),"Tab did not navigate");var layer=System.Windows.Documents.AdornerLayer.GetAdornerLayer(focused);var adorners=layer==null?null:layer.GetAdorners(focused);Check(adorners!=null&&adorners.Length>0,"Keyboard focus adorner not visible");Capture(theme+"-keyboard-tab-focus",(FrameworkElement)VisualTreeHelper.GetChild(window,0));}panel.Children.Remove(b);});
    Test("A12 100 real Demo navigations, hidden clocks and recording preparation drawer",()=>{ShellWindow shell=null;try{shell=new ShellWindow(true){Width=960,Height=720,ShowInTaskbar=false,Owner=window};shell.Show();shell.InitializeRuntime().GetAwaiter().GetResult();shell.Activate();Pump();Check(shell.Demo&&shell.Macros==null,"Demo initialized real recording controller");for(int i=0;i<100;i++){shell.Navigate(i%4);Pump(2);}Pump(1400);Check(SpringMotion.ActiveCount==0&&!SpringMotion.RenderingSubscribed,"Navigation retained active springs");var flags=BindingFlags.Instance|BindingFlags.NonPublic;var views=(FrameworkElement[])typeof(ShellWindow).GetField("views",flags).GetValue(shell);foreach(var view in views)if(!view.IsVisible)Check(!view.HasAnimatedProperties,"Hidden page kept opacity clock");var macro=typeof(ShellWindow).GetField("macroPage",flags).GetValue(shell);foreach(var theme in new[]{"classic","fluent"}){Ui.ApplyTheme(theme);shell.Navigate(1);Pump();macro.GetType().GetMethod("OpenRecording",flags).Invoke(macro,null);Check(shell.DrawerOpen&&!((MacroPage)macro).IsRecording&&shell.Macros==null,"Preparation preview started recorder");var root=(FrameworkElement)VisualTreeHelper.GetChild(shell,0);var samples=new List<string>{"elapsed_ms"};var clock=Stopwatch.StartNew();for(int i=0;i<12;i++){Pump(25);Capture(theme+"-recording-preparation-"+i.ToString("D2"),root);samples.Add(clock.ElapsedMilliseconds.ToString());}File.WriteAllLines(Path.Combine(output,theme+"-recording-preparation.csv"),samples);Capture(theme+"-recording-preparation-drawer",root);shell.CloseDrawer();shell.Navigate(2);clock.Restart();samples=new List<string>{"elapsed_ms"};for(int i=0;i<12;i++){Pump(25);Capture(theme+"-page-navigation-"+i.ToString("D2"),root);samples.Add(clock.ElapsedMilliseconds.ToString());}File.WriteAllLines(Path.Combine(output,theme+"-page-navigation.csv"),samples);}shell.Hide();Pump();Check(SpringMotion.ActiveCount==0&&!SpringMotion.RenderingSubscribed,"Hidden shell keeps rendering");}finally{if(shell!=null)shell.ClosePreview();window.Activate();Pump();UiMotion.SettleAll();}});
    foreach(string theme in new[]{"classic","fluent"}){Ui.ApplyTheme(theme);Ui.ReducedMotion=true;primary.IsEnabled=ordinary.IsEnabled=toggle.IsEnabled=true;foreach(int width in new[]{1180,960,760}){window.Width=width;Pump();Capture(theme+"-"+width+"-components",panel);}Ui.ReducedMotion=false;Record(theme+"-disable-interruption",()=>Mouse(primary,true),()=>primary.IsEnabled=false);primary.IsEnabled=true;Record(theme+"-focus-interruption",()=>SendKey(toggle,true,Key.Space),()=>toggle.RaiseEvent(new KeyboardFocusChangedEventArgs(Keyboard.PrimaryDevice,0,toggle,ordinary){RoutedEvent=Keyboard.LostKeyboardFocusEvent}));}
   }finally{UiMotion.SettleAll();window.Close();app.Shutdown();File.WriteAllLines(Path.Combine(output,"results.tsv"),results);}
   Console.WriteLine("STAGE A: "+(results.Count-failed)+" PASS / "+failed+" FAIL");return failed==0?0:1;
  }
 }
}
